import { useCallback, useMemo, useState } from 'react';
import { getRawLead } from '../utils/recordInlineEditUtils';
import { ROW_MODAL } from '../constants/rowModalKeys';

export { ROW_MODAL };

export default function useRowModals() {
  const [activeModal, setActiveModal] = useState(null);
  const [selectedRow, setSelectedRow] = useState(null);

  const openRowModal = useCallback((modalKey, row) => {
    setSelectedRow(getRawLead(row));
    setActiveModal(modalKey);
  }, []);

  const closeRowModal = useCallback(() => {
    setActiveModal(null);
    setSelectedRow(null);
  }, []);

  const needsStatusContext = useMemo(
    () => activeModal === ROW_MODAL.FORM_DETAIL || activeModal === ROW_MODAL.MANAGE,
    [activeModal]
  );

  return {
    activeModal,
    selectedRow,
    openRowModal,
    closeRowModal,
    needsStatusContext,
    isCommentOpen: activeModal === ROW_MODAL.COMMENT,
    isManageOpen: activeModal === ROW_MODAL.MANAGE,
    isFormDetailOpen: activeModal === ROW_MODAL.FORM_DETAIL,
    isStatusLogsOpen: activeModal === ROW_MODAL.STATUS_LOGS,
    isImagesOpen: activeModal === ROW_MODAL.IMAGES,
    isQuickCallOpen: activeModal === ROW_MODAL.QUICK_CALL,
  };
}
