import React, { useMemo } from 'react';
import { Box } from '@mui/material';
import { DataTable, EmptyState, TableSkeleton } from '../../../../../components/ui';
import useBusinessFunctionsTableSx from '../../../hooks/useBusinessFunctionsTableSx';
import { buildStatusLogTableColumns } from '../../config/statusLogTableColumns';
import { RECORD_COPY } from '../../constants/recordCopy';

export default function StatusLogsTable({
  rows = [],
  loading = false,
  selectedPayloadFields = [],
  onTemplateClick,
  isMobile = false,
}) {
  const { tableOverrides } = useBusinessFunctionsTableSx();

  const columns = useMemo(
    () => buildStatusLogTableColumns({
      rows,
      selectedPayloadFields,
      onTemplateClick,
    }),
    [onTemplateClick, rows, selectedPayloadFields]
  );

  const tableMaxHeight = isMobile
    ? 'calc(100dvh - 220px)'
    : 'min(60vh, 520px)';

  return (
    <Box
      sx={{
        width: '100%',
        minWidth: 0,
        overflow: 'hidden',
      }}
    >
      <DataTable
        columns={columns}
        data={rows}
        loading={loading}
        getRowId={(row) => String(row._rowKey || row._id || row.id)}
        aria-label={RECORD_COPY.statusLogs.title}
        enableStickyHeader
        layoutMode="grid"
        emptyState={
          <EmptyState
            title={RECORD_COPY.statusLogs.empty}
            description=""
            sx={{ py: { xs: 4, sm: 6 } }}
          />
        }
        skeleton={<TableSkeleton rowCount={6} columnCount={Math.max(columns.length, 6)} />}
        muiTableHeadCellProps={tableOverrides.muiTableHeadCellProps}
        muiTableBodyCellProps={tableOverrides.muiTableBodyCellProps}
        muiTableBodyRowProps={tableOverrides.muiTableBodyRowProps}
        muiTableContainerProps={{
          ...tableOverrides.muiTableContainerProps,
          sx: {
            ...(tableOverrides.muiTableContainerProps?.sx || {}),
            maxHeight: tableMaxHeight,
            overflowX: 'auto',
            overflowY: 'auto',
            WebkitOverflowScrolling: 'touch',
          },
        }}
      />
    </Box>
  );
}
