import APIService from '../../../../Services/APIService';
import { Apis } from '../../../../Services/app.constants';
import {
  extractResolvedTemplateId,
  getTemplateIdFromRow,
  normalizeApiList,
  normalizeStatusValue,
} from '../utils/statusLogUtils';

export const recordTemplateSummaryService = {
  async resolveTemplateId({ row, templateName, botNumber = '' }) {
    const directId = getTemplateIdFromRow(row, templateName);
    if (directId) return directId;

    try {
      const response = await APIService.get(
        `${Apis.whatsappTemplate}?bot_number=${encodeURIComponent(botNumber || '')}&name=${encodeURIComponent(templateName || '')}`
      );

      if (response?.status !== 200 && response?.status !== 201) {
        return '';
      }

      const resolved = extractResolvedTemplateId(response);
      if (resolved) return resolved;

      const result = response?.data ?? response;
      if (Array.isArray(result)) {
        const matched = result.find(
          (item) => normalizeStatusValue(item?.name || item?.template_name)
            === normalizeStatusValue(templateName)
        ) || result[0];

        const arrayId = matched?.id || matched?.template_id || matched?.md_id || '';
        return arrayId ? String(arrayId) : '';
      }

      return '';
    } catch {
      return '';
    }
  },

  async getDateWiseSummary(templateId, { startDate = '', endDate = '' } = {}) {
    if (!templateId) throw new Error('Template ID is required');

    const query = new URLSearchParams({
      template_id: String(templateId),
      start_date: startDate || '',
      end_date: endDate || '',
      next_page: '0',
      sort_by: 'sent_date',
      order: 'desc',
      limit: '20',
    });

    const response = await APIService.get(`${Apis.getTemplateDateWiseSumnary}?${query.toString()}`);
    return normalizeApiList(response);
  },

  async getUserSummary(templateId, date, params = {}) {
    if (!templateId || !date) {
      return { users: [], total: 0, raw: null };
    }

    let apiDate = date;
    if (date.includes('T')) {
      apiDate = date.split('T')[0];
    } else if (date.includes(' ')) {
      apiDate = date.split(' ')[0];
    }

    const query = new URLSearchParams({
      template_id: String(templateId),
      date: apiDate,
      next_page: String(params.page ?? 0),
      search: params.search ?? '',
      status: params.status ?? '',
      assigned_to: params.assigned_to ?? '',
      sort_by: params.sortField ?? 'total_users',
      order: params.sortOrder ?? 'desc',
      limit: String(params.limit ?? 10),
      template_status: params.template_status ?? '',
    });

    const response = await APIService.get(`${Apis.getTemplateUserSummary}?${query.toString()}`);
    const users = normalizeApiList(response);
    const payload = response?.data ?? response;

    const total = Number(
      payload?.total_count
      ?? payload?.total_users
      ?? payload?.data?.total_count
      ?? payload?.data?.total_users
      ?? users.length
    ) || users.length;

    return { users, total, raw: response };
  },
};
