import React, { useMemo } from 'react';
import { Box, Grid, Typography } from '@mui/material';
import { DataTable, EmptyState, TableSkeleton } from '../../../../../../components/ui';
import { useFeatureTheme } from '../../../../../../theme/hooks/useFeatureTheme';
import useBusinessFunctionsTableSx from '../../../../hooks/useBusinessFunctionsTableSx';
import { buildTemplateStatusHistoryColumns } from '../../../config/statusLogTableColumns';
import { RECORD_COPY } from '../../../constants/recordCopy';
import { formatStatusLogDate, getTemplateNamesFromRow, normalizeStatusValue } from '../../../utils/statusLogUtils';

function filterStatusRowsByTemplate(statusRows = [], templateName = '') {
  if (!templateName) return [];
  const target = normalizeStatusValue(templateName);

  return statusRows.filter((row) => {
    const names = getTemplateNamesFromRow(row);
    return names.some((name) => normalizeStatusValue(name) === target);
  });
}

function DetailCard({ label, value, semantic, typography }) {
  return (
    <Box
      sx={{
        p: 1.5,
        border: `1px solid ${semantic.borders.border}`,
        borderRadius: 2,
        minWidth: 0,
        bgcolor: semantic.surfaces.surface,
      }}
    >
      <Typography
        sx={{
          fontSize: typography.fontSizeXs,
          color: semantic.text.secondary,
          display: 'block',
          mb: 0.5,
        }}
      >
        {label}
      </Typography>
      <Typography
        sx={{
          fontSize: typography.fontSizeSm,
          fontWeight: typography.fontWeightSemibold,
          color: semantic.text.primary,
          wordBreak: 'break-word',
        }}
      >
        {value || '-'}
      </Typography>
    </Box>
  );
}

export default function StatusLogTemplateDetailsTab({
  selectedTemplate,
  templateDetailKeys = [],
  statusRows = [],
  isMobile = false,
}) {
  const { semantic, typography } = useFeatureTheme();
  const { tableOverrides } = useBusinessFunctionsTableSx();
  const copy = RECORD_COPY.statusLogs.template;
  const templateData = selectedTemplate?.data || {};

  const templateStatusRows = useMemo(
    () => filterStatusRowsByTemplate(statusRows, selectedTemplate?.name),
    [selectedTemplate?.name, statusRows]
  );

  const historyColumns = useMemo(() => buildTemplateStatusHistoryColumns(), []);
  const tableMaxHeight = isMobile ? 'calc(100dvh - 360px)' : 320;

  return (
    <Box sx={{ minWidth: 0 }}>
      <Grid container spacing={1.5}>
        <Grid item xs={12} sm={6} md={3}>
          <DetailCard
            label={copy.fields.name}
            value={selectedTemplate?.name}
            semantic={semantic}
            typography={typography}
          />
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <DetailCard
            label={copy.fields.status}
            value={templateData?.status || templateData?.template_status}
            semantic={semantic}
            typography={typography}
          />
        </Grid>
        <Grid item xs={12} sm={6} md={3}>
          <DetailCard
            label={copy.fields.sentCreated}
            value={formatStatusLogDate(selectedTemplate?.sentDate)}
            semantic={semantic}
            typography={typography}
          />
        </Grid>

        {templateDetailKeys.map((key) => (
          <Grid item xs={12} sm={6} md={3} key={key}>
            <DetailCard
              label={key}
              value={
                typeof templateData[key] === 'object'
                  ? JSON.stringify(templateData[key])
                  : String(templateData[key] ?? '-')
              }
              semantic={semantic}
              typography={typography}
            />
          </Grid>
        ))}
      </Grid>

      <Typography
        sx={{
          mt: 3,
          mb: 1.5,
          fontSize: typography.fontSizeMd,
          fontWeight: typography.fontWeightSemibold,
          color: semantic.text.primary,
        }}
      >
        {copy.statusHistory}
      </Typography>

      <Box
        sx={{
          border: `1px solid ${semantic.borders.border}`,
          borderRadius: 2,
          overflow: 'hidden',
          minWidth: 0,
        }}
      >
        <DataTable
          columns={historyColumns}
          data={templateStatusRows}
          getRowId={(row) => String(row._rowKey || row._id || row.id || row.updated_at || 'status-row')}
          enableStickyHeader
          layoutMode="grid"
          emptyState={<EmptyState title={RECORD_COPY.statusLogs.empty} description="" />}
          skeleton={<TableSkeleton rowCount={4} columnCount={4} />}
          muiTableHeadCellProps={tableOverrides.muiTableHeadCellProps}
          muiTableBodyCellProps={tableOverrides.muiTableBodyCellProps}
          muiTableContainerProps={{
            sx: {
              maxHeight: tableMaxHeight,
              overflowX: 'auto',
              overflowY: 'auto',
              WebkitOverflowScrolling: 'touch',
            },
          }}
        />
      </Box>
    </Box>
  );
}
