import { useCallback, useMemo, useState } from 'react';

export default function useRecordSelection(rows = []) {
  const [rowSelection, setRowSelection] = useState({});

  const selectedCount = useMemo(
    () => Object.values(rowSelection).filter(Boolean).length,
    [rowSelection]
  );

  const selectedRows = useMemo(() => {
    const selectedIds = Object.keys(rowSelection).filter((id) => rowSelection[id]);
    return rows.filter((row) => selectedIds.includes(String(row.id)));
  }, [rowSelection, rows]);

  const selectedLeadIds = useMemo(
    () => selectedRows
      .map((row) => row._rawLead?.lead_id ?? row.lead_id)
      .filter(Boolean),
    [selectedRows]
  );

  const selectedRecordIds = useMemo(
    () => selectedRows
      .map((row) => row._mongoId ?? row._rawLead?.id ?? row.id)
      .filter(Boolean),
    [selectedRows]
  );

  const clearSelection = useCallback(() => {
    setRowSelection({});
  }, []);

  return {
    rowSelection,
    setRowSelection,
    selectedCount,
    selectedRows,
    selectedLeadIds,
    selectedRecordIds,
    clearSelection,
  };
}
