import React from 'react';
import { Avatar, Box, Typography } from '@mui/material';
import {
  getRecordLeadDisplayId,
  getRecordPhoneNumber,
} from '../../../records/utils/recordInteractiveColumnUtils';
import { getRawLead } from '../../../records/utils/recordInlineEditUtils';

const AVATAR_COLORS = ['#059669', '#2563EB', '#7C3AED', '#DB2777', '#D97706', '#0891B2'];

function hashString(value = '') {
  let hash = 0;
  for (let i = 0; i < value.length; i += 1) {
    hash = value.charCodeAt(i) + ((hash << 5) - hash);
  }
  return Math.abs(hash);
}

function getContactName(row) {
  const rawLead = getRawLead(row);
  if (rawLead?.contact_name) {
    return String(rawLead.contact_name).trim();
  }

  const data = Array.isArray(rawLead?.data) ? rawLead.data : [];
  const match = data.find((entry) => {
    const key = String(entry?.key_name ?? '').toLowerCase();
    return ['contact_name', 'name', 'contactname', 'customer_name'].includes(key);
  });

  return match?.value ? String(match.value).trim() : '';
}

function getAvatarLabel(row) {
  const contactName = getContactName(row);
  if (contactName) return contactName[0]?.toUpperCase() ?? 'R';

  const leadId = getRecordLeadDisplayId(row);
  if (leadId) return String(leadId).slice(-1).toUpperCase();

  const phone = getRecordPhoneNumber(row);
  if (phone) return phone.slice(-1);

  return 'R';
}

function getAvatarColor(seed = '') {
  return AVATAR_COLORS[hashString(seed) % AVATAR_COLORS.length];
}

export default function LeadPrimaryCell({ row, onView }) {
  const leadId = getRecordLeadDisplayId(row);
  const phone = getRecordPhoneNumber(row);
  const contactName = getContactName(row);
  const title = contactName || leadId || 'Record';
  const subtitle = contactName && leadId ? leadId : phone;
  const avatarSeed = contactName || leadId || phone || 'record';

  return (
    <Box sx={{ display: 'flex', alignItems: 'center', gap: 1.25, minWidth: 0 }}>
      <Avatar
        sx={{
          width: 32,
          height: 32,
          fontSize: '0.8125rem',
          fontWeight: 700,
          bgcolor: getAvatarColor(avatarSeed),
          flexShrink: 0,
        }}
      >
        {getAvatarLabel(row)}
      </Avatar>
      <Box sx={{ minWidth: 0, flex: 1 }}>
        <Typography
          component="span"
          onClick={(event) => {
            event.stopPropagation();
            onView?.(row);
          }}
          sx={{
            display: 'block',
            fontSize: '0.8125rem',
            fontWeight: 600,
            color: 'primary.main',
            lineHeight: 1.35,
            cursor: onView ? 'pointer' : 'default',
            overflow: 'hidden',
            textOverflow: 'ellipsis',
            whiteSpace: 'nowrap',
            '&:hover': onView ? { textDecoration: 'underline' } : undefined,
          }}
        >
          {title}
        </Typography>
        {subtitle ? (
          <Typography
            component="span"
            sx={{
              display: 'block',
              fontSize: '0.75rem',
              color: 'text.secondary',
              lineHeight: 1.3,
              overflow: 'hidden',
              textOverflow: 'ellipsis',
              whiteSpace: 'nowrap',
            }}
          >
            {subtitle}
          </Typography>
        ) : null}
      </Box>
    </Box>
  );
}
