import React from 'react';
import { Box, Typography } from '@mui/material';
import ChevronLeftIcon from '@mui/icons-material/ChevronLeft';
import TableChartIcon from '@mui/icons-material/TableChart';
import GroupsIcon from '@mui/icons-material/Groups';
import PersonOutlineIcon from '@mui/icons-material/PersonOutline';
import FilterAltIcon from '@mui/icons-material/FilterAlt';
import TaskAltIcon from '@mui/icons-material/TaskAlt';
import AssignmentIcon from '@mui/icons-material/Assignment';

const ICON_MAP = {
  Groups: GroupsIcon,
  PersonOutline: PersonOutlineIcon,
  FilterAlt: FilterAltIcon,
  TaskAlt: TaskAltIcon,
  Assignment: AssignmentIcon,
};

export default function TableRecordsHeader({
  table,
  totalCount,
  styles,
  onBack,
}) {
  const IconComp = ICON_MAP[table?.iconName] || TableChartIcon;

  return (
    <Box sx={styles.tableRecordsHeaderRoot}>
      <Box
        component="button"
        type="button"
        onClick={onBack}
        sx={styles.tableRecordsBackLink}
        aria-label="Back to all tables"
      >
        <ChevronLeftIcon className="table-records-back-chevron" sx={styles.tableRecordsBackIcon} />
        <Typography component="span" sx={styles.tableRecordsBackLabel}>
          All Tables
        </Typography>
      </Box>

      <Box sx={styles.tableRecordsHero}>
        <Box sx={styles.tableRecordsIconWrap}>
          <IconComp fontSize="small" />
        </Box>

        <Box sx={styles.tableRecordsHeroText}>
          <Typography component="h2" sx={styles.tableRecordsTitle}>
            {table?.name}
          </Typography>

          <Box sx={styles.tableRecordsMeta}>
            <Typography component="span" sx={styles.tableRecordsMetaItem}>
              {totalCount.toLocaleString()} records
            </Typography>
            <Box component="span" sx={styles.tableRecordsMetaDot} aria-hidden="true" />
            <Typography component="span" sx={styles.tableRecordsMetaItem}>
              Campaign table
            </Typography>
          </Box>
        </Box>
      </Box>
    </Box>
  );
}
