import React, { useCallback, useEffect, useMemo, useRef, useState } from 'react';
import { Box, Alert, useMediaQuery, useTheme } from '@mui/material';
import { useRecoilValue } from 'recoil';
import {
  getColumnVisibilityFromFormObject,
  updateFormObjectForColumnVisibility,
} from '../../../../../components/Leads/DynamicFormFields/helper.ts';
import { useSnackBar } from '../../../../../components/FlowBuilder/Common/SnackBar/index.tsx';
import { userInformationAtom } from '../../../../../Services/_states';
import { Button, Dialog, TableLayout } from '../../../../../components/ui';
import useBusinessFunctionsTableSx from '../../../hooks/useBusinessFunctionsTableSx';
import useTableRecords from '../../../hooks/useTableRecords';
import TableRecordsHeader from './TableRecordsHeader';
import TableRecordsList from './TableRecordsList';
import useRecordForm from '../../../records/hooks/useRecordForm';
import useRecordPermissions from '../../../records/hooks/useRecordPermissions';
import useRecordFilters from '../../../records/hooks/useRecordFilters';
import useRecordSelection from '../../../records/hooks/useRecordSelection';
import useStatusContext from '../../../records/hooks/useStatusContext';
import useTableStatusList from '../../../records/hooks/useTableStatusList';
import useInlineEdit from '../../../records/hooks/useInlineEdit';
import StatusConfirmDialog from '../../../records/components/StatusConfirmDialog';
import { buildOptionColorsByAlias } from '../../../records/utils/recordInlineEditUtils';
import RecordDrawer from '../../../records/components/RecordDrawer';
import RecordsToolbar, { RecordsFilterSummary } from '../../../records/components/RecordsToolbar';
import FiltersPanel from '../../../records/components/FiltersPanel';
import ColumnsMenu from '../../../records/components/ColumnsMenu';
import BulkActionsBar from '../../../records/components/BulkActionsBar';
import DownloadModal from '../../../records/components/DownloadModal';
import HelpModal from '../../../records/components/HelpModal';
import useRecordNavigation from '../../../records/hooks/useRecordNavigation';
import useRowModals from '../../../records/hooks/useRowModals';
import useColumnModals from '../../../records/hooks/useColumnModals';
import RowActionsModals from '../../../records/components/RowActionsModals';
import ColumnModals from '../../../records/components/ColumnModals';
import {
  buildRecordFormFields,
  buildRecordFormGroups,
} from '../../../records/utils/recordFormFieldsUtils';
import { buildColumnVisibilityState } from '../../../records/adapters/recordFiltersAdapter';
import { orderRecordTableColumns } from '../../../records/utils/recordTableColumnUtils';
import { recordService } from '../../../records/services/recordService';
import { RECORD_COPY } from '../../../records/constants/recordCopy';
import { ROW_MODAL } from '../../../records/constants/rowModalKeys';

export default function TableRecordsPanel({
  workspaceId,
  table,
  styles,
  onBack,
  showHeader = true,
  accountId,
}) {
  const theme = useTheme();
  const isMobile = useMediaQuery(theme.breakpoints.down('sm'));
  const { showSnackBar } = useSnackBar();
  const loggedInUser = useRecoilValue(userInformationAtom);
  const profileId = loggedInUser?.profile?.id ?? loggedInUser?.id;
  const organisationId = loggedInUser?.profile?.organisation?.organisation_id;

  const { tableOverrides } = useBusinessFunctionsTableSx();
  const safeTableOverrides = tableOverrides ?? {};
  const permissions = useRecordPermissions(workspaceId, accountId);

  const [search, setSearch] = useState('');
  const [page, setPage] = useState(0);
  const [pageSize, setPageSize] = useState(10);
  const [refreshToken, setRefreshToken] = useState(0);
  const [sorting, setSorting] = useState([]);
  const [columnsMenuOpen, setColumnsMenuOpen] = useState(false);
  const [columnVisibility, setColumnVisibility] = useState({});
  const columnVisibilityContextRef = useRef(null);
  const [isSavingView, setIsSavingView] = useState(false);
  const [downloadOpen, setDownloadOpen] = useState(false);
  const [helpOpen, setHelpOpen] = useState(false);
  const [deleteRecordTarget, setDeleteRecordTarget] = useState(null);

  const {
    filters,
    panelOpen: filtersOpen,
    filterAnchorEl,
    activeFilterCount,
    openPanel: openFilters,
    closePanel: closeFilters,
    applyFilters,
    clearFilters,
  } = useRecordFilters();

  const sortBy = sorting[0]?.id || '';
  const sortType = sorting[0]?.desc ? 'desc' : sorting[0]?.id ? 'asc' : '';

  const {
    columns,
    rows,
    totalCount,
    uniquePhoneCount,
    isLoading,
    error,
    formPayload,
    refetch,
  } = useTableRecords({
    workspaceId,
    tableId: table?.id,
    formItems: table?.leadsFormItems,
    search,
    page,
    pageSize,
    sortBy,
    sortType,
    filters,
    refreshToken,
  });

  const {
    rowSelection,
    setRowSelection,
    selectedCount,
    selectedLeadIds,
    selectedRecordIds,
    selectedRows,
    clearSelection,
  } = useRecordSelection(rows);

  const handleSaved = useCallback(() => {
    setRefreshToken((token) => token + 1);
    refetch();
  }, [refetch]);

  const recordForm = useRecordForm({
    table,
    onSaved: handleSaved,
  });

  const recordFormItems = table?.leadsFormItems || formPayload?.leads_form_items;

  const { typeOfStatusList } = useTableStatusList(table?.id);

  const optionColorsByAlias = useMemo(
    () => buildOptionColorsByAlias(recordFormItems),
    [recordFormItems]
  );

  const inlineEdit = useInlineEdit({
    tableId: table?.id,
    onSuccess: handleSaved,
  });

  const navigation = useRecordNavigation({
    accountId,
    workspaceId,
    tableId: table?.id,
    formPayload,
    table,
  });

  const rowModals = useRowModals();
  const columnModals = useColumnModals();

  const handleOpenWebForm = useCallback((row) => {
    if (!permissions.canOpenWebForm) return;

    const result = navigation.openWebForm(row);
    if (!result?.ok && result?.reason === 'invalidPhone') {
      showSnackBar(RECORD_COPY.errors.phoneUnavailable, 'error');
    }
  }, [navigation, permissions.canOpenWebForm, showSnackBar]);

  const columnActions = useMemo(
    () => ({
      onViewRecord: (row) => recordForm.openRecord(row, 'view'),
      onOpenWebForm: handleOpenWebForm,
      onOpenAudioSummary: columnModals.openAudioSummary,
      onOpenAiChat: columnModals.openAiChat,
      canOpenWebForm: permissions.canOpenWebForm,
      canAddComment: permissions.canAddComment,
      onOpenComment: (row) => rowModals.openRowModal(ROW_MODAL.COMMENT, row),
    }),
    [
      columnModals.openAiChat,
      columnModals.openAudioSummary,
      handleOpenWebForm,
      permissions.canAddComment,
      permissions.canOpenWebForm,
      recordForm.openRecord,
      rowModals.openRowModal,
    ]
  );

  const dynamicFormFields = useMemo(
    () => buildRecordFormFields(recordFormItems, profileId),
    [profileId, recordFormItems]
  );

  const dynamicFormGroups = useMemo(
    () => buildRecordFormGroups(formPayload),
    [formPayload]
  );

  const rowPermissions = useMemo(
    () => ({
      canEdit: permissions.canEdit,
      canDelete: permissions.canDelete,
      canAddComment: permissions.canAddComment,
      canManageRecord: permissions.canManageRecord,
      canViewFormDetail: permissions.canViewFormDetail,
      canViewStatusLogs: permissions.canViewStatusLogs,
      canViewImages: permissions.canViewImages,
      canQuickCall: permissions.canQuickCall,
    }),
    [permissions]
  );

  useStatusContext({
    open: recordForm.drawerOpen || rowModals.needsStatusContext,
    workspaceId,
    table,
    webForm: recordForm.webForm,
    formItems: recordFormItems,
  });

  useEffect(() => {
    setSearch('');
    setPage(0);
    setSorting([]);
    clearSelection();
    clearFilters();
    setColumnVisibility({});
    columnVisibilityContextRef.current = null;
  }, [table?.id, clearFilters, clearSelection]);

  useEffect(() => {
    if (!formPayload || !columns.length || !table?.id) return;

    const contextKey = `${table.id}:${profileId ?? ''}`;
    if (columnVisibilityContextRef.current === contextKey) return;

    const saved = getColumnVisibilityFromFormObject(formPayload, profileId);
    setColumnVisibility(buildColumnVisibilityState(columns, saved));
    columnVisibilityContextRef.current = contextKey;
  }, [columns, formPayload, profileId, table?.id]);

  const visibleColumnsMeta = useMemo(() => {
    const filtered = columns.filter((column) => {
      if (isMobile && column.priority === false && columnVisibility[column.key] === false) {
        return false;
      }
      return columnVisibility[column.key] !== false;
    });

    return orderRecordTableColumns(filtered);
  }, [columns, columnVisibility, isMobile]);

  const columnsMenuItems = useMemo(
    () => orderRecordTableColumns(columns),
    [columns]
  );

  const handleToggleColumn = useCallback((key) => {
    setColumnVisibility((prev) => ({
      ...prev,
      [key]: prev[key] === false,
    }));
  }, []);

  const handleSetAllColumnsVisible = useCallback((visible) => {
    setColumnVisibility((prev) => {
      const next = { ...prev };
      columns.forEach((column) => {
        if (column?.key) {
          next[column.key] = visible;
        }
      });
      return next;
    });
  }, [columns]);

  const handleResetColumns = useCallback(() => {
    setColumnVisibility(buildColumnVisibilityState(columns, {}));
  }, [columns]);

  const handleSaveView = useCallback(async () => {
    if (!table?.id || !formPayload) return;
    setIsSavingView(true);
    try {
      const updatedForm = updateFormObjectForColumnVisibility(
        columnVisibility,
        formPayload,
        profileId
      );
      const res = await recordService.saveFormColumnVisibility(table.id, updatedForm);
      if (res?.status === 200) {
        showSnackBar(RECORD_COPY.success.viewSaved, 'success');
      } else {
        showSnackBar('Failed to save column view', 'error');
      }
    } catch (err) {
      showSnackBar('Failed to save column view', 'error');
    } finally {
      setIsSavingView(false);
    }
  }, [columnVisibility, formPayload, profileId, showSnackBar, table?.id]);

  const handleDeleteRecord = useCallback(async (rawLead) => {
    setDeleteRecordTarget(rawLead);
  }, []);

  const handleConfirmDeleteRecord = useCallback(async () => {
    const deleted = await recordForm.deleteRecord(deleteRecordTarget);
    if (deleted) {
      handleSaved();
    }
    setDeleteRecordTarget(null);
  }, [deleteRecordTarget, handleSaved, recordForm]);

  return (
    <Box sx={{ mt: 0.5 }}>
      {showHeader ? (
        <TableRecordsHeader
          table={table}
          totalCount={totalCount}
          styles={styles}
          onBack={onBack}
        />
      ) : null}

      {error ? (
        <Alert severity="error" sx={{ mt: 2 }}>
          {error}
        </Alert>
      ) : null}

      <Box sx={{ mt: 2.5, display: 'flex', flexDirection: 'column', gap: 2 }}>
        <RecordsToolbar
          styles={styles}
          search={{
            value: search,
            placeholder: `Search ${table?.name?.toLowerCase() || 'records'}...`,
            onChange: (value) => {
              setSearch(value);
              setPage(0);
            },
          }}
          onRefresh={() => {
            setRefreshToken((token) => token + 1);
            refetch();
          }}
          onAddRecord={permissions.canCreate ? recordForm.openCreate : undefined}
          onOpenFilters={permissions.canFilter ? openFilters : undefined}
          onOpenColumns={() => setColumnsMenuOpen(true)}
          filterCount={activeFilterCount}
          canCreate={permissions.canCreate}
          canFilter={permissions.canFilter}
          totalCount={totalCount}
          uniquePhoneCount={uniquePhoneCount}
          permissions={permissions}
          onDownload={() => setDownloadOpen(true)}
          onEnterRecords={navigation.navigateToEnterRecords}
          onImportRecords={navigation.navigateToImportRecords}
          onEditForm={navigation.navigateToEditForm}
        />

        <RecordsFilterSummary
          count={activeFilterCount}
          onClear={clearFilters}
          styles={styles}
        />

        <BulkActionsBar
          selectedCount={selectedCount}
          selectedLeadIds={selectedLeadIds}
          selectedRecordIds={selectedRecordIds}
          workspaceId={workspaceId}
          workspaceName={table?.campaignName || table?.name}
          tableId={table?.id}
          table={table}
          formItems={recordFormItems}
          organisationId={organisationId}
          canDelete={permissions.canDelete}
          canBulkUpdate={permissions.canBulkUpdate}
          onClear={clearSelection}
          onSuccess={handleSaved}
          styles={styles}
        />

        <TableLayout
          variant="flat"
          sx={safeTableOverrides.tableLayout}
          pagination={{
            page,
            pageSize,
            totalCount,
            onPageChange: setPage,
            onPageSizeChange: (nextPageSize) => {
              setPageSize(nextPageSize);
              setPage(0);
            },
          }}
        >
          <TableRecordsList
            rows={rows}
            columnsMeta={visibleColumnsMeta}
            loading={isLoading}
            page={page}
            pageSize={pageSize}
            tableOverrides={safeTableOverrides}
            enableSorting
            sorting={sorting}
            onSortingChange={setSorting}
            enableRowSelection={permissions.canBulkUpdate || permissions.canDelete}
            rowSelection={rowSelection}
            onRowSelectionChange={setRowSelection}
            onRowClick={(row) => recordForm.openRecord(row, 'view')}
            canEdit={permissions.canEdit}
            canDelete={permissions.canDelete}
            rowPermissions={rowPermissions}
            onEdit={(rawLead) => recordForm.openRecord(rawLead, 'edit')}
            onDelete={handleDeleteRecord}
            onOpenRowModal={rowModals.openRowModal}
            typeOfStatusList={typeOfStatusList}
            optionColorsByAlias={optionColorsByAlias}
            onRequestStatusUpdate={inlineEdit.requestStatusUpdate}
            onEntityChange={inlineEdit.updateEntity}
            columnActions={columnActions}
          />
        </TableLayout>
      </Box>

      <RecordDrawer
        open={recordForm.drawerOpen}
        mode={recordForm.mode}
        selectedRecord={recordForm.selectedRecord}
        dynamicFormData={recordForm.dynamicFormData}
        fieldErrors={recordForm.fieldErrors}
        formEnable={recordForm.formEnable}
        formDataLoading={recordForm.formDataLoading}
        isLoading={recordForm.isLoading}
        isFormDirty={recordForm.isFormDirty}
        isReadOnly={recordForm.isReadOnly}
        isCreating={recordForm.isCreating}
        hasFormFields={recordForm.hasFormFields}
        onClose={recordForm.requestCloseDrawer}
        onFieldChange={recordForm.handleFieldChange}
        onSave={recordForm.saveRecord}
        onEdit={recordForm.startEdit}
      />

      <FiltersPanel
        open={filtersOpen}
        anchorEl={filterAnchorEl}
        onClose={closeFilters}
        appliedFilters={filters}
        onApply={(nextFilters) => {
          applyFilters(nextFilters);
          setPage(0);
        }}
        onClear={(nextFilters) => {
          clearFilters(nextFilters);
          setPage(0);
        }}
        formItems={table?.leadsFormItems || formPayload?.leads_form_items}
        tableId={table?.id}
        workspaceId={workspaceId}
        styles={styles}
      />

      <ColumnsMenu
        open={columnsMenuOpen}
        onClose={() => setColumnsMenuOpen(false)}
        columns={columnsMenuItems}
        columnVisibility={columnVisibility}
        onToggleColumn={handleToggleColumn}
        onSetAllColumnsVisible={handleSetAllColumnsVisible}
        onResetColumns={handleResetColumns}
        styles={styles}
      />

      <StatusConfirmDialog
        open={inlineEdit.confirmOpen}
        title={inlineEdit.confirmTitle}
        message={inlineEdit.confirmMessage}
        isSubmitting={inlineEdit.isUpdating}
        onConfirm={inlineEdit.confirmStatusUpdate}
        onCancel={inlineEdit.closeConfirm}
      />

      <Dialog
        open={Boolean(deleteRecordTarget)}
        onClose={() => setDeleteRecordTarget(null)}
        title={RECORD_COPY.deleteConfirm.title}
        maxWidth="xs"
        actions={
          <>
            <Button variant="ghost" onClick={() => setDeleteRecordTarget(null)}>
              {RECORD_COPY.deleteConfirm.cancel}
            </Button>
            <Button variant="destructive" onClick={handleConfirmDeleteRecord}>
              {RECORD_COPY.deleteConfirm.confirmSingle}
            </Button>
          </>
        }
      >
        {RECORD_COPY.deleteConfirm.message}
      </Dialog>

      <DownloadModal
        open={downloadOpen}
        onClose={() => setDownloadOpen(false)}
        workspaceId={workspaceId}
        tableId={table?.id}
        columns={columns}
        columnVisibility={columnVisibility}
        filters={filters}
        search={search}
        activeFilterCount={activeFilterCount}
      />

      {/* <HelpModal
        open={helpOpen}
        onClose={() => setHelpOpen(false)}
        tableId={table?.id}
      /> */}

      <ColumnModals
        columnModals={columnModals}
        onRecordUpdated={handleSaved}
      />

      <RowActionsModals
        rowModals={rowModals}
        workspaceId={workspaceId}
        tableId={table?.id}
        dynamicFormFields={dynamicFormFields}
        dynamicFormGroups={dynamicFormGroups}
        onRecordUpdated={handleSaved}
      />
    </Box>
  );
}
