import { useCallback, useEffect, useMemo, useState } from 'react';
import { recordService } from '../services/recordService';
import { buildTypeOfStatusList } from '../utils/dynamicFilterUtils';

export default function useTableStatusList(tableId) {
  const [statusList, setStatusList] = useState([]);
  const [isLoading, setIsLoading] = useState(false);

  useEffect(() => {
    if (!tableId) {
      setStatusList([]);
      return undefined;
    }

    let cancelled = false;
    setIsLoading(true);

    recordService.fetchStatusList(tableId).then((list) => {
      if (!cancelled) {
        setStatusList(Array.isArray(list) ? list : []);
        setIsLoading(false);
      }
    });

    return () => {
      cancelled = true;
    };
  }, [tableId]);

  const typeOfStatusList = useMemo(
    () => buildTypeOfStatusList(statusList),
    [statusList]
  );

  return {
    statusList,
    typeOfStatusList,
    isLoading,
  };
}
