import React from 'react';
import { Box, Typography } from '@mui/material';
import AddCommentOutlinedIcon from '@mui/icons-material/AddCommentOutlined';
import { EllipsisWithTooltip } from '../../../../../components/Shared/Tables/TableV1.tsx';
import { RECORD_COPY } from '../../constants/recordCopy';
import { getLastCommentText } from '../../utils/recordInteractiveColumnUtils';
import RecordToolbarIconButton from '../RecordToolbarIconButton';

function stopRowClick(event) {
  event.stopPropagation();
}

export default function RecordCommentCell({
  row,
  value,
  canAddComment = false,
  onOpenComment,
}) {
  const text = (getLastCommentText(row) || value || '').trim();
  const canOpen = Boolean(onOpenComment && (canAddComment || text));

  const handleOpen = (event) => {
    stopRowClick(event);
    onOpenComment?.(row);
  };

  return (
    <Box
      className="record-cell-action"
      onClick={stopRowClick}
      sx={{
        display: 'flex',
        alignItems: { xs: 'flex-start', sm: 'center' },
        gap: { xs: 0.5, sm: 0.75 },
        minWidth: 0,
        width: '100%',
        py: 0.25,
      }}
    >
      <Box
        sx={{
          minWidth: 0,
          flex: 1,
          cursor: canOpen ? 'pointer' : 'default',
        }}
        onClick={canOpen ? handleOpen : undefined}
        role={canOpen ? 'button' : undefined}
        tabIndex={canOpen ? 0 : undefined}
        onKeyDown={
          canOpen
            ? (event) => {
                if (event.key === 'Enter' || event.key === ' ') {
                  event.preventDefault();
                  handleOpen(event);
                }
              }
            : undefined
        }
      >
        {text ? (
          <EllipsisWithTooltip text={text} maxWidth="100%" />
        ) : (
          <Typography
            variant="body2"
            sx={{
              color: 'text.secondary',
              fontStyle: 'italic',
              fontSize: '0.8125rem',
              lineHeight: 1.45,
            }}
          >
            {RECORD_COPY.comments.noCommentPreview}
          </Typography>
        )}
      </Box>

      {canAddComment ? (
        <Box sx={{ flexShrink: 0, alignSelf: { xs: 'flex-start', sm: 'center' } }}>
          <RecordToolbarIconButton
            title={RECORD_COPY.rowActions.addComment}
            ariaLabel={RECORD_COPY.rowActions.addComment}
            onClick={handleOpen}
            icon={<AddCommentOutlinedIcon />}
          />
        </Box>
      ) : null}
    </Box>
  );
}
