const PRIORITY_COLUMN_KEYS = new Set([
  'lead_id',
  'phone_number',
  'created_at',
  'status',
]);

export function isPriorityColumn(key) {
  return PRIORITY_COLUMN_KEYS.has(key);
}

export function applyPriorityColumnVisibility(columns = [], isMobile = false) {
  if (!isMobile) return columns;
  return columns.map((column) => ({
    ...column,
    hidden: column.hidden ?? !isPriorityColumn(column.key),
  }));
}

export function buildColumnVisibilityState(columnsMeta = [], savedVisibility = {}) {
  const visibility = {};
  columnsMeta.forEach((column) => {
    const keyName = column?.fieldMeta?.key_name;
    const candidates = [
      column.key,
      keyName,
      keyName ? `data.${keyName}` : null,
    ].filter(Boolean);
    const savedKey = candidates.find((key) => savedVisibility[key] !== undefined);

    if (savedKey) {
      visibility[column.key] = savedVisibility[savedKey];
    } else {
      visibility[column.key] = true;
    }
  });
  return visibility;
}

export function countActiveFilters(filters = {}) {
  let count = 0;
  if (filters.search) count += 1;
  if (filters.start_date || filters.end_date) count += 1;
  if (filters.status) count += 1;
  if (filters.lead_assigned_to) count += 1;
  if (Array.isArray(filters.dynamicFilters)) {
    count += filters.dynamicFilters.filter((rule) => {
      if (!rule) return false;
      const keyName = rule.key_name || rule?.matched_with?.key_name;
      return Boolean(keyName && rule.operator);
    }).length;
  }
  return count;
}

export function buildRecordsQueryParams({
  workspaceId,
  tableId,
  search = '',
  page = 0,
  pageSize = 10,
  sortBy = '',
  sortType = '',
  filters = {},
}) {
  const normalizedSortType = (() => {
    if (sortType === 'desc') return -1;
    if (sortType === 'asc') return 1;
    return '';
  })();

  const params = {
    campaign_id: String(workspaceId),
    leads_form_id: String(tableId),
    limit: pageSize,
    page,
    offset: page * pageSize,
    search: search || '',
    start_date: filters.start_date || '',
    end_date: filters.end_date || '',
    status: filters.status || '',
    lead_assigned_to: filters.lead_assigned_to || '',
    is_pending: filters.is_pending ?? '',
  };

  if (sortBy && normalizedSortType !== '') {
    params.sort_by = sortBy;
    params.sort_type = normalizedSortType;
  }

  if (Array.isArray(filters.dynamicFilters) && filters.dynamicFilters.length > 0) {
    params.data_filters = JSON.stringify(filters.dynamicFilters);
  }

  return params;
}
