import { useCallback, useMemo, useState } from 'react';
import { countActiveFilters } from '../adapters/recordFiltersAdapter';

export const EMPTY_CAMPAIGN_FILTERS = {
  start_date: '',
  end_date: '',
  status: '',
  lead_assigned_to: '',
  is_pending: '',
  statusObj: null,
  assigneeObj: null,
  dynamicFilters: [],
};

export default function useRecordFilters() {
  const [filters, setFilters] = useState(EMPTY_CAMPAIGN_FILTERS);
  const [panelOpen, setPanelOpen] = useState(false);
  const [filterAnchorEl, setFilterAnchorEl] = useState(null);

  const openPanel = useCallback((event) => {
    setFilterAnchorEl(event?.currentTarget ?? null);
    setPanelOpen(true);
  }, []);

  const closePanel = useCallback(() => {
    setPanelOpen(false);
    setFilterAnchorEl(null);
  }, []);

  const applyFilters = useCallback((nextFilters) => {
    setFilters(nextFilters || EMPTY_CAMPAIGN_FILTERS);
    setPanelOpen(false);
    setFilterAnchorEl(null);
  }, []);

  const clearFilters = useCallback((nextFilters) => {
    setFilters(nextFilters || EMPTY_CAMPAIGN_FILTERS);
  }, []);

  const activeFilterCount = useMemo(
    () => countActiveFilters(filters),
    [filters]
  );

  return {
    filters,
    panelOpen,
    filterAnchorEl,
    activeFilterCount,
    openPanel,
    closePanel,
    applyFilters,
    clearFilters,
  };
}
