import { colors } from '../../../theme/tokens/colors';

const HEADER_BG = '#F8FAFC';
const BORDER_COLOR = colors.grey[200];
const BORDER_STRONG = colors.grey[300];
const ROW_HOVER = colors.grey[50];
const CELL_PADDING_X = 12;

/** Lead / workspace record table — Templates-inspired compact styling. */
export function createBusinessFunctionsTableOverrides({ semantic, accent } = {}) {
  const table = semantic?.table ?? {};
  const borderColor = table.borderColor ?? BORDER_COLOR;

  return {
    muiTableHeadCellProps: {
      sx: {
        backgroundColor: `${HEADER_BG} !important`,
        color: `${colors.grey[700]} !important`,
        fontSize: '0.6875rem',
        fontWeight: 700,
        letterSpacing: '0.06em',
        textTransform: 'uppercase',
        borderBottom: `1px solid ${BORDER_STRONG}`,
        py: 0.75,
        px: `${CELL_PADDING_X}px`,
        height: 40,
        whiteSpace: 'nowrap',
        '&, & *': {
          color: `${colors.grey[700]} !important`,
        },
        '& .Mui-TableHeadCell-Content': {
          color: `${colors.grey[700]} !important`,
        },
        '& .Mui-TableHeadCell-Content-Labels': {
          color: `${colors.grey[700]} !important`,
        },
        '& .MuiTypography-root': {
          fontSize: '0.6875rem !important',
          fontWeight: '700 !important',
          letterSpacing: '0.06em',
          textTransform: 'uppercase',
          color: `${colors.grey[700]} !important`,
        },
        '& .MuiTableSortLabel-root': {
          color: `${colors.grey[700]} !important`,
          opacity: 1,
        },
        '& .MuiTableSortLabel-icon': {
          color: `${colors.grey[600]} !important`,
          opacity: '1 !important',
          fontSize: '1rem',
        },
        '& .Mui-TableHeadCell-Content': {
          justifyContent: 'flex-start',
        },
      },
    },
    muiTableHeadRowProps: {
      sx: {
        backgroundColor: HEADER_BG,
        boxShadow: 'none',
      },
    },
    muiTableBodyCellProps: {
      sx: {
        fontSize: '0.8125rem',
        color: colors.grey[800],
        backgroundColor: colors.white,
        borderBottom: `1px solid ${borderColor}`,
        py: 0.5,
        px: `${CELL_PADDING_X}px`,
        height: 44,
        lineHeight: 1.4,
        verticalAlign: 'middle',
        whiteSpace: 'nowrap',
      },
    },
    muiTableBodyRowProps: {
      sx: {
        backgroundColor: colors.white,
        height: 44,
        transition: 'background-color 120ms ease',
        '&:hover td': {
          backgroundColor: `${ROW_HOVER} !important`,
        },
        '&:last-child td': {
          borderBottom: 'none',
        },
      },
    },
    muiTableContainerProps: {
      sx: {
        width: '100%',
        maxWidth: '100%',
        overflowX: 'auto',
        WebkitOverflowScrolling: 'touch',
      },
    },
    actionColumnHeadCell: {
      position: 'sticky',
      right: 0,
      zIndex: 3,
      backgroundColor: `${HEADER_BG} !important`,
      boxShadow: '-6px 0 10px rgba(15, 23, 42, 0.06)',
    },
    actionColumnBodyCell: {
      position: 'sticky',
      right: 0,
      zIndex: 1,
      backgroundColor: `${colors.white} !important`,
      boxShadow: '-6px 0 10px rgba(15, 23, 42, 0.06)',
    },
    tableLayout: {
      '& [data-testid="table-layout-surface"]': {
        borderColor,
        borderRadius: 0,
        boxShadow: '0 1px 2px rgba(15, 23, 42, 0.04)',
        overflow: 'hidden',
      },
    },
    accentPrimary: accent?.primary,
  };
}

export function createBusinessFunctionsTableFilters({ semantic } = {}) {
  const borders = semantic?.borders ?? {};
  const borderColor = borders.border ?? BORDER_COLOR;
  const surface = semantic?.surfaces?.surface ?? colors.white;

  return {
    root: {
      display: 'flex',
      flexDirection: 'row',
      alignItems: 'center',
      flexWrap: { xs: 'wrap', md: 'nowrap' },
      gap: 1.5,
      width: '100%',
    },
    search: {
      width: { xs: '100%', sm: 300 },
      maxWidth: { md: 340 },
      flexShrink: 0,
      '& > div:last-of-type': {
        bgcolor: surface,
        borderColor,
        boxShadow: '0 1px 2px rgba(16, 24, 40, 0.04)',
        minHeight: 34,
        transition: 'border-color 140ms ease, box-shadow 140ms ease',
        '&:focus-within': {
          boxShadow: '0 0 0 3px rgba(37, 99, 235, 0.08)',
        },
      },
    },
  };
}
